css_extra:
.tone-dark { --turn:#14B1BF; }
.btn { font-family:'Josefin Sans',sans-serif; padding-top:3px; }
.btn.primary, .tone-dark .btn.primary { background:#14B1BF; color:#FFFFFF; }
.label { font-family:'Josefin Sans',sans-serif; }
[data-name="Watermark"] svg { opacity:.1; }
.tone-dark [data-name="Watermark"] svg { filter:brightness(0) invert(1); opacity:.09; }
.tick i { background: url(assets/crown-colour.png) center/18px auto no-repeat; border-radius:0; width:22px; }
.tick i svg { display:none; }
.tone-dark .tick i { background-image:url(assets/crown-white.png); }
.tone-dark .card.tone-card .tick i { background-image:url(assets/crown-colour.png); }
[data-name="Hero"] .tick { border:1.5px solid rgba(255,255,255,.5); background:rgba(255,255,255,.07); border-radius:10px; padding:12px 16px; align-items:center; }
[data-name="Hero"] .tick i { background-image:url(assets/crown-colour.png); margin-top:0; }
[data-name="Hero"] .tick span { font-weight:500; }
.tone-light [data-name="Story"], .tone-light [data-name="Review"] { border:1px solid #D5E7E8; box-shadow:0 12px 30px rgba(6,68,75,.06); }
[data-name="Offer seal"] { background:#14B1BF !important; border-color:rgba(255,255,255,.6) !important; box-shadow:0 18px 40px rgba(0,0,0,.18); }
[data-name="Offer seal"] > div:first-child { border-color:rgba(255,255,255,.55) !important; }
[data-name="Offer seal"] .label { color:#FFFFFF; }
.label { line-height:1.6; }
[data-name="Practice tour video"] > .label { display:none; }
